190		\begin{align*}
191			A^{\mathsf{Point},\, u}_{a_1,\ldots,a_k} \ot I_{\mathrm B}
192			&\simeq_{\delta_{\mathrm{ld}}}
193			I_{\mathrm A} \ot G^{\mathrm B}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]}\;,\\
194			G^{\mathrm A}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]} \ot I_{\mathrm B}
195			&\simeq_{\delta_{\mathrm{ld}}}
196			I_{\mathrm A} \ot B^{\mathsf{Point},\, u}_{a_1,\ldots,a_k}\;,\\
197			G^{\mathrm A}_{g_1,\ldots,g_k} \ot I_{\mathrm B}
198			&\simeq_{\delta_{\mathrm{ld}}}
199			I_{\mathrm A} \ot G^{\mathrm B}_{g_1,\ldots,g_k}\;,
200		\end{align*}
